 if(action==='delete-record'){view={type:'delete',id:b.dataset.id};return showDialog(dialogHeader('删除这笔记录')+'<div class="dialog-content"><p>删除后将重新计算账户余额和统计。</p><div class="dialog-actions"><button class="secondary" data-action="cancel-delete">保留记录</button><button class="text-danger" data-action="confirm-delete">确认删除</button></div></div>')}
 if(action==='cancel-delete')return showRecord(view.id);
 if(action==='confirm-delete'){const id=view.id;return commit(next=>{W.removeRows(next,[id])}).then(()=>{closeDialog();toast('已删除账单')}).catch(e=>error(e.message))}
 if(action==='settings')return settingsDialog();
 if(action==='ocr')return ocrDialog();
 if(action==='filters')return filtersDialog();
 if(action==='remove-filter'){delete filters[b.dataset.name];return render()}
 if(action==='reset-filters'){filters={};query='';closeDialog();return render()}
 if(action==='more-records')return loadMoreRecords('search');
 if(action==='book-records'){filters={book:b.dataset.name};query='';return go('search')}
 if(action==='workspace-books'){closeDialog();return go('books')}
 if(action==='new-book')return simpleForm('新建用途账本','<label>账本名称<input name="name" maxlength="40" placeholder="例如：旅行手记" required></label>','book-form');
 if(action==='budget')return simpleForm('每月预算',`<p class="intro">收入和转账不冲减预算。</p><label>预算金额<input name="budget" inputmode="decimal" value="${esc(state.prefs.budgets.__global_monthly__)}" required></label>`,'budget-form');
 if(action==='export-csv')return download('StarLedger-paper.csv',L.csv(state.rows),'text/csv;charset=utf-8');
