document.addEventListener('click',async e=>{const record=e.target.closest('[data-entry]');if(record){if(relationSelection){if(relationSaving)return;const id=record.dataset.entry;if(id===relationSelection.source){toast('这笔是关联的起始账单');return}relationSelection.ids.has(id)?relationSelection.ids.delete(id):relationSelection.ids.add(id);refreshRecordList();return}if(features.selecting()){features.toggle(record.dataset.entry);searchResults()}else showRecord(record.dataset.entry);return}const key=e.target.closest('[data-key]');if(key){keypad(key.dataset.key);return}const b=e.target.closest('[data-action]');if(b){e.preventDefault();try{await actions(b.dataset.action,b)}catch(err){error(err.message)}}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('tr[data-entry]')){e.preventDefault();e.target.click()}if(e.target.id==='entry-amount'&&e.key==='Enter'){e.preventDefault();calculate()}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.draft&&draft){draft[t.dataset.draft]=t.type==='checkbox'?t.checked:t.value;return}if(t.id==='existing-query')existingResults(t.value);if(features.input(t))return;if(t.id==='entry-amount'&&draft){draft.amount=normalizeAmountExpression(t.value).replace(/[^0-9.+−×÷]/g,'').slice(0,48);t.value=draft.amount}if(t.id==='account-query'){accountQuery=t.value;accountResults()}if(t.id==='search-query'){query=t.value;searchLimit=40;searchResults()}if(t.id==='category-query'){pickerQuery=t.value;categoryResults()}if(t.id==='picker-account-query'){pickerQuery=t.value;accountPickerResults()}});
document.addEventListener('change',async e=>{const t=e.target;try{if(await features.change(t))return;if(t.id==='report-book'){reportBook=t.value;render();return}if(t.id==='report-account'){reportAccount=t.value;render();return}if(t.id==='account-type'){accountType=t.value;accountResults()}if(t.id==='theme-setting'){setTheme(t.value);await commit(n=>n.prefs.appearance=theme)}if(t.id==='record-title-setting'){await commit(n=>n.prefs.recordTitle=t.value);toast('显示方式已保存')}if(t.id==='cycle-setting'||t.id==='account-sort'){const key=t.id==='cycle-setting'?'monthStartDay':'entryAccountSortMode',value=key==='monthStartDay'?Number(t.value):t.value;await commit(next=>next.prefs[key]=value);toast('设置已保存')}if(t.dataset.draft&&draft){draft[t.dataset.draft]=t.type==='checkbox'?t.checked:t.value;if(t.dataset.draft==='currency'){draft.more=true;showEntry()}}}catch(err){error(err.message)}});
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('entry-more')&&draft)draft.more=e.target.open},true);
document.addEventListener('focusin',e=>{if(draft&&e.target.matches('[data-draft]')&&e.target.tagName!=='SELECT')$('#dialog').classList.add('text-editing')});
document.addEventListener('focusout',()=>requestAnimationFrame(()=>{if(!document.activeElement?.matches('[data-draft]'))$('#dialog').classList.remove('text-editing')}));
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;settingsOrigin=null;settingsLastPanel=f.closest('.settings-panel')||settingsLastPanel;const data=Object.fromEntries(new FormData(f));try{
 if(await features.submit(f,data))return;
 if(f.id==='split-form'){const total=amountSaveValue(draft.amount),part=amountSaveValue(data.amount);if(!total.ok||!part.ok||part.value<=0||part.value>=total.value)throw Error('拆出金额须大于零且小于原金额');const clone=structuredClone(draft);clone.id='';clone._key=crypto.randomUUID();clone._previous=null;clone.amount=part.value.toFixed(2);draft.amount=L.round(total.value-part.value).toFixed(2);task.drafts.splice(task.active+1,0,clone);const temp=taskState();R.link(temp,[draft._key,clone._key]);task.relations=temp.relations;showEntry();return}
 if(f.id==='task-relations-form'){const ids=new FormData(f).getAll('member'),roles=Object.fromEntries(ids.map(id=>[id,data['role-'+id]])),temp=taskState();const old=R.forBill(temp,draft._key);if(old)R.unlink(temp,old.members.filter(m=>!ids.includes(m.id)).map(m=>m.id));R.link(temp,ids,roles);task.relations=temp.relations;showEntry();return}
 if(f.id==='new-category-form'){if(!data.category.trim()||!data.subcategory.trim())throw Error('请填写大小类名称');draft.category=data.category.trim();draft.subcategory=data.subcategory.trim();showEntry();return}
 if(f.id==='filter-form'){if(data.from&&data.to&&data.from>data.to)throw Error('开始日期不能晚于结束日期');filters=data;searchLimit=40;closeDialog();render();return}
 if(f.id==='budget-form'){const value=Number(data.budget);if(!Number.isFinite(value)||value<0||value>1e12)throw Error('预算金额无效');await commit(next=>next.prefs.budgets.__global_monthly__=value);if(!$('.settings-root'))closeDialog();toast('预算已更新');return}
 if(f.id==='book-form'){const name=data.name.trim();if(!name||state.prefs.books.includes(name))throw Error('请使用一个新的账本名称');await commit(next=>next.prefs.books.push(name));closeDialog();go('books');return}
 if(f.id==='account-form'){const old=view.name,name=data.name.trim();if(!name||['__proto__','constructor','prototype'].includes(name)||/[,，\r\n]/.test(name))throw Error('请填写有效账户名称');if(name!==old&&state.prefs.accountProfiles[name])throw Error('已存在同名账户');const previous=L.profile(state,old);if(old&&data.currency!==previous.currency&&data.balance==='')throw Error('更换主币种时请同时填写实际余额进行校准');const balance=data.balance===''?null:Number(data.balance);if(balance!==null&&(!Number.isFinite(balance)||Math.abs(balance)>1e12))throw Error('余额无效');if(data.limit&&(!Number.isFinite(Number(data.limit))||Number(data.limit)<0))throw Error('信用额度无效');if(data.cnyRate&&(!(Number(data.cnyRate)>0)||!Number.isFinite(Number(data.cnyRate))))throw Error('汇率必须大于零');await commit(next=>{if(old&&old!==name){next.rows=next.rows.map(r=>({...r,account:r.account===old?name:r.account,account2:r.account2===old?name:r.account2}));delete next.prefs.accountProfiles[old];for(const id of Object.keys(next.prefs.accountOrder))next.prefs.accountOrder[id]=next.prefs.accountOrder[id].filter(n=>n!==old)}next.prefs.accountProfiles[name]={...previous,type:data.type,groupId:data.groupId,currency:data.currency,cnyRate:data.cnyRate?Number(data.cnyRate):'',note:data.note,icon:data.icon||'',include:data.include==='on',hidden:data.hidden==='on',limit:data.limit||''};if(balance!==null){const raw=L.accountViews(next).find(a=>a.name===name)?.raw||0;next.prefs.accountProfiles[name].calibration={balance,baseline:raw}}for(const g of Object.keys(next.prefs.accountOrder))if(g!==data.groupId)next.prefs.accountOrder[g]=next.prefs.accountOrder[g].filter(n=>n!==name);const order=next.prefs.accountOrder[data.groupId]??=[];if(!order.includes(name))order.push(name)});showAccount(name);toast('账户已保存');return}
 if(f.id==='ocr-form'){const parser=window.StarLedgerRecognizer;if(!parser)throw Error('识别器尚未就绪');const result=parser.recognize(data.text,{rows:state.rows,historyRows:state.rows,accounts:Object.keys(state.prefs.accountProfiles)}),source=result.records?.length?result.records:[result],value=f=>f?.value??'',seeds=source.map(r=>({type:value(r.type)||'支出',amount:String(value(r.amount)||''),merchant:value(r.merchant),note:value(r.note),...(value(r.category)?{category:value(r.category)}:{}),...(value(r.subcategory)?{subcategory:value(r.subcategory)}:{}),...(state.prefs.accountProfiles[value(r.account)]?{account:value(r.account),currency:L.profile(state,value(r.account)).currency,fxRate:L.profile(state,value(r.account)).cnyRate||''}:{}),...(value(r.date)?{date:String(value(r.date)).replace(' ','T').slice(0,16)}:{}),...(value(r.account2)?{account2:value(r.account2)}:{}),ocr:true}));if(source.length===1&&(data.text.match(/^[\s]*[+−-]\s*[¥￥]?\s*\d+[.,]\d{2}\s*$/gm)||[]).length>1)throw Error('检测到多个金额，但无法确定每笔边界；请补充每笔日期时间或分别粘贴');beginTask(source.map(()=>null),seeds);for(const h of result.relationHints||[]){const ids=h.members.map(i=>task.drafts[i]?._key).filter(Boolean);if(ids.length>=2){const temp=taskState();R.link(temp,ids,Object.fromEntries(ids.map((id,i)=>[id,h.roles?.[i]||'auto'])));task.relations=temp.relations}}draftBaseline=JSON.stringify(task);showEntry();return}

}catch(err){error(err.message)}});

